#include <vector>
#define main hecbench_original_main
#include "blockexchange-cuda/main.cu"
#undef main
void emit(int trial,double seconds,const std::vector<double>&result,const std::vector<double>&expected,int repeat,double atol=0.,double rtol=0.){
 double error=0;bool correct=result.size()==expected.size();for(size_t i=0;i<result.size();i++){double e=fabs(result[i]-expected[i]);error=fmax(error,e);correct &= std::isfinite(result[i])&&e<=atol+rtol*fabs(expected[i]);}char path[64];snprintf(path,sizeof(path),"trial_%d.bin",trial);FILE*f=fopen(path,"wb");fwrite(result.data(),8,result.size(),f);fclose(f);
 printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.12g,\"timing_region\":\"synchronized_kernel_loop_mean\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,correct?"true":"false",result.size(),error,repeat,path,result.size());if(!correct)exit(1);
}
int main(int argc,char**argv){int n=argc>1?atoi(argv[1]):4096,repeat=argc>2?atoi(argv[2]):10;std::vector<int>input(n),out(n);std::vector<double>expected(n);for(int i=0;i<n;i++)input[i]=i;for(int i=0;i<n;i++)expected[i]=input[(i/1024)*1024+(i%4)*256+(i%1024)/4];int *di,*dr;cudaMalloc(&di,n*4);cudaMalloc(&dr,n*4);cudaMemcpy(di,input.data(),n*4,cudaMemcpyHostToDevice);k<256,1024><<<(n+255)/256,256>>>(di,dr,n);cudaDeviceSynchronize();for(int trial=1;trial<=5;trial++){auto start=std::chrono::steady_clock::now();for(int j=0;j<repeat;j++)k<256,1024><<<(n+255)/256,256>>>(di,dr,n);cudaDeviceSynchronize();double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/repeat;cudaMemcpy(out.data(),dr,n*4,cudaMemcpyDeviceToHost);std::vector<double>values(out.begin(),out.end());emit(trial,seconds,values,expected,repeat);}cudaFree(di);cudaFree(dr);return 0;}
